
CREATE TABLE ETL_PROCESS.T_ETL_ORDER_HEADER_1 (
   WSHOP_CD                            VARCHAR(5)      COMMENT 'The unique code for the Lidl webshop, where an order can be placed by a customer. The webshop is defined per political country.',
   DIST_CHANNEL_CD                     VARCHAR(5)      COMMENT 'The code for the distribution channel ( a channel  through which the goods are sold )',
   DIST_ZONE_CD                        VARCHAR(25)     COMMENT 'The unique code for the Lidl webshop zones, where an order can be placed by a customer. The zones are defined per official administrative divisions per country.',
   CUST_ORDER_SID                      NUMBER          NOT NULL COMMENT 'The unique identifier  for customer order ( can be return or intercompany order)',
   CUST_SID                            NUMBER          COMMENT 'Customer who made the order',
   SALES_DOCUMENT_TYPE_CD              VARCHAR(8)      COMMENT 'The code for the the delivery document ( C (Order), H (Return), I (Order w/o charge), V (Purchase Order) )',
   SALES_CHANNEL_TYPE_CD               VARCHAR(5)      COMMENT 'The code for the device which was being used to order from the online webshop. Possible values are desktop browser, iOS or Android.',
   CUST_ORDER_NR                       VARCHAR(20)     NOT NULL COMMENT 'The original order number of the source system',
   CUST_ORDER_TYPE_CD                  VARCHAR(5)      COMMENT 'The differenciation whether the order will be fulfilled by Lidl (=intercompany) or a supplier_1 directly (= extracompnay).',
   CUST_ORDER_DT                       DATE            COMMENT 'The date when order was made',
   PRCD_ELEMENTS_CONDITION_NR          VARCHAR(20)     COMMENT 'ETL support field - reference to t_etl_prcd_elements_position_1',
   SALES_SEGMENT_TYPE_CD               VARCHAR(20)     COMMENT 'The unique identifier (surrogate key) for the sales_1 channel ',
   ORDER_CANCEL_REASON_CD              VARCHAR(5)      COMMENT 'The code for reason why the customer has cancelled or got been cancelled an order line/product',
   CUST_PAYM_METHOD_CD                 VARCHAR(5)      COMMENT 'The code for the payment methods',
   DELIVERY_ADDR_SID                   NUMBER          COMMENT 'The unique identifier (surrogate key) for the addresses',
   DELIVERY_CUST_SID                   NUMBER          COMMENT 'The unique identifier (surrogate key) for the customer',
   IS_ORDER_MIGRATED_FG                BOOLEAN         COMMENT 'An indicator showing whether the order is migrated or not',
   IS_BLOCKED_DELIVERY_FG              BOOLEAN         COMMENT 'Flag which tells whether a delivery is being blocked currently. e.g. if customer orders with payment type \"Vorauskasse\" then the delivery will only start as soon as the money arrives',
   DELIVERY_BLOCKED_REASON_CD          VARCHAR(5)      COMMENT 'The code with the reason why the delivery is blocked for the specific customer order.',
   CURR_CD                             VARCHAR(5)      COMMENT 'Currency code in which order has been payed',
   IS_LIDL_GIFT_CARD_FG                BOOLEAN         COMMENT 'True if lidl gift card was used in the sales_1 order',
   LIDL_GIFT_CARD_LOCAL_VAL            NUMBER(38, 5)   COMMENT 'Amount of lidl gift card used in a sales_1 order',
   CUST_ORDER_REF_NR                   VARCHAR(100)    COMMENT 'Customer reference no, incase of migrated sales_1 orders: original sales_1 order nr in legacy system',
   SALES_DOCUMENT_REASON_CD            VARCHAR(5)      COMMENT 'The reason code for the sales_1 document',
   LEAD_SRC_LOG_SYS_CD                 VARCHAR(100)    COMMENT 'Technical field - source code',
   LEAD_SRC_NAME                       VARCHAR(100)    COMMENT 'Technical field - source name ',
   OVERALL_PROCESSING_STATUS_CD        VARCHAR(5)      COMMENT 'Code for the processing status_1 of the entire sales_1 document',
   OVERALL_PROCESSING_STATUS_NR        NUMBER          COMMENT 'Generated Number for the code for the processing status_1 of the entire sales_1 document',
   CUST_ORDER_TMSP                     TIMESTAMP_LTZ(9) COMMENT 'Date and time (in UTC) when the customer finished check-out in the online shop, thus issuing the sale order.',
   DIST_CHANNEL_TYPE_CD                VARCHAR(5)      COMMENT 'A  type of distribution channel ( Wshop for LD Webshop , IC for Intercompany)',
   DIST_COUNTRY_CD                     VARCHAR(5)      COMMENT 'The unique code for a country_1 according to ISO-3166 Alpha-2. E.g. \"DE\" for Germany or \"FR\" for France',
   DWH_CREATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   DWH_UPDATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',
   DWH_SRC_FILE_NAME                   VARCHAR(255)    NOT NULL COMMENT 'The path and the name of the file(s) from which this record was loaded.',
   SRC_FILE_TMSP                       TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was extracted from the source.',   
   CONSTRAINT PK_T_ETL_ORDER_HEADER PRIMARY KEY (CUST_ORDER_SID) NOT ENFORCED 
)  COMMENT = 'ETL - The order placed from a customer within the onlineshop to receive the wanted items. Such orders can be also cancelled, returned or free resends to customers. Table contain also return orders and Intercompany orders ( orders placed on Kaufland online shop and delivered by Lidl)';
